// Handle file processing response
const fileProcessingResult = $('Process Uploaded Files').item(0).json;
const originalInput = $('Parse Chat Input').item(0).json;

// Combine file content with original query
let enhancedQuery = originalInput.userQuery;

if (fileProcessingResult.extractedText) {
  enhancedQuery = `Kullanıcı sorusu: ${originalInput.userQuery}\n\nYüklenen dosya içeriği:\n${fileProcessingResult.extractedText}`;
}

// Return enhanced data for further processing
return [{
  json: {
    ...originalInput,
    userQuery: enhancedQuery,
    processedFiles: fileProcessingResult.processedFiles || [],
    hasProcessedFiles: true
  }
}];

// Error handling for the workflow
const error = $json.error || 'Bilinmeyen bir hata oluştu.';
const originalInput = $('Parse Chat Input').first()?.json || {};

// Log error for debugging
console.error('Workflow Error:', {
  error,
  customerId: originalInput.customerId,
  widgetId: originalInput.widgetId,
  query: originalInput.userQuery,
  timestamp: new Date().toISOString()
});

// Prepare user-friendly error response
const errorResponse = {
  output: 'Üzgünüm, şu anda teknik bir sorun yaşıyoruz. Lütfen birkaç dakika sonra tekrar deneyin.',
  followUpPrompts: [
    'Tekrar deneyin',
    'Farklı bir soru sorun',
    'Destek ile iletişime geçin'
  ],
  metadata: {
    error: true,
    timestamp: new Date().toISOString(),
    locale: originalInput.metadata?.locale || 'tr'
  }
};

return [{
  json: errorResponse
}];
